/*
 * A272864  Palindromes that are not of the form x^2 + y^2 + z^2 where x, y, z
 *          are integers.
 * https://oeis.org/A272864
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, look
 * Formula:   a(n) is the nth decimal palindrome that can be expressed as *
 *            4^k (8m + 7), i.e. it is NOT representable as x² + y² + z² for
 *            integers * x, y, z. The sequence is generated by enumerating
 *            palindromes in * increasing order and keeping those whose value
 *            satisfies Legendre’s * three‑square theorem con...
 * Range:     u8 n <= 6, u16 n <= 134, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

/* power of ten, result held in idx_t.  k is small enough for idx_t. */
static idx_t pow10_idx(idx_t k) {
    idx_t p = 1;
    while (k--) p *= 10;
    return p;
}

/* reverse decimal digits of x (x fits in idx_t). */
static idx_t reverse_digits(idx_t x) {
    idx_t rev = 0;
    while (x) {
        rev = rev * 10 + (x % 10);
        x /= 10;
    }
    return rev;
}

/* true iff n is of the form 4^a (8b + 7). */
static bool is_legendre_form(seq_t n) {
    /* n is unsigned so modulo and division are defined. */
    while ((n % 4) == 0U) n /= 4U;
    return (n % 8U) == 7U;
}

/* The required sequence function. */
seq_t a(idx_t n) {
    if (n == 0) return 0;                     /* undefined for n<1 */
    const idx_t max_seq_idx = (idx_t)(~(seq_t)0);   /* maximum value of seq_t */

    idx_t count = 0;                           /* number of acceptable palins found */

    for (idx_t length = 1; ; ++length) {
        /* halfLen = ceil(length / 2), integer division works. */
        idx_t halfLen = (length + 1) >> 1;
        idx_t powLow  = pow10_idx(halfLen - 1);   /* 10^(halfLen-1) */
        idx_t powHigh = pow10_idx(halfLen);       /* 10^halfLen      */

        /* If even the smallest palindrome of this length exceeds max seq_t,
           no further palindromes can be used. */
        if (powLow > max_seq_idx) break;

        idx_t start = powLow;           /* first half part (most significant digit can't be 0) */
        idx_t end   = powHigh - 1;      /* last half part */

        for (idx_t h = start; h <= end; ++h) {
            idx_t rev;
            idx_t pow;          /* multiplier for the first half */
            if (length & 1U) {  /* odd length */
                rev = reverse_digits(h / 10U);
                pow = powLow;
            } else {            /* even length */
                rev = reverse_digits(h);
                pow = powHigh;
            }

            /* Avoid overflow of h * pow in idx_t.  If it would overflow past
               max_seq_idx, the resulting palindrome would also exceed
               max_seq_idx, so we can stop exploring this length. */
            if (pow != 0 && h > max_seq_idx / pow) break;
            idx_t prod = h * pow;
            idx_t pal_idx = prod + rev;
            if (pal_idx > max_seq_idx) break;      /* further h gives larger palindromes */

            seq_t pal = (seq_t)pal_idx;
            if (is_legendre_form(pal)) {
                ++count;
                if (count == n) return pal;
            }
        }
    }
    /* Should never reach here for valid inputs. */
    return 0;
}
